using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
using UnityEngine;
using SpatialWallpaper.Sdk;
using SpatialWallpaper.Sdk.Native;
namespace SpatialWallpaper.Content {
 public static class NativeContentConfiguration {
  public static NativePlatformCatalog Platform(){var text=UnityEngine.Resources.Load<TextAsset>("SpatialWallpaper/NativePlatformIndex");if(!text)throw new InvalidDataException("native-platform-index-missing");return new NativePlatformCatalog(text.text);}
  static string Digest(string path){using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}
  public static async Task PrepareInputAsync(JObject config,string dataRoot,int[] region){var specification=config["script"] as JObject;if(specification==null)return;var admitted=NativeScriptDefinition.Admit(File.ReadAllBytes((string)specification["launch"]["program"]));if(!admitted.CapabilityTags.Contains("input"))return;string descriptor=await NativeBrokerLease.EnsureAsync(dataRoot);string runtime=ContentArguments.Argument("--sdk-runtime")??Path.GetFullPath(Path.Combine(Application.dataPath,"../sdk-runtime"));config["input"]=new JObject{{"helper",Path.Combine(runtime,"SpatialWallpaper.Preview.exe")},{"cache",Path.Combine(dataRoot,"native-input-bootstrap")},{"descriptor",descriptor},{"region",new JArray(region)}};}
  public static JObject Configure(JObject config,ContentStore store,string work,string revision,string dataRoot,bool preview){
   var package=store.OpenNativeBuild(work,revision,Platform());var manifest=package.Manifest;string runtime=Path.Combine(Path.GetDirectoryName(Application.dataPath),"native-runtime");var runtimeManifest=JsonData.Parse(File.ReadAllText(Path.Combine(runtime,"native-runtime.json")));JsonData.Require((string)runtimeManifest["sdk"]==SceneCommandCatalog.TargetSdk&&(int?)runtimeManifest["schema"]==5&&(int?)runtimeManifest["scene_command_abi"]==SceneCommandCatalog.Abi&&(string)runtimeManifest["catalog_digest"]==SceneCommandCatalog.Digest,"native-runtime-identity");
   var files=runtimeManifest["files"] as JObject;JsonData.Require(files!=null&&files.Count<256,"native-runtime-files");foreach(var file in files.Properties()){JsonData.Require(file.Name.Length<240&&!file.Name.Contains('\\')&&!file.Name.Contains(':')&&!file.Name.Split('/').Any(segment=>segment.Length==0||segment=="."||segment==".."),"native-runtime-path");string path=Path.Combine(runtime,file.Name);for(string parent=Path.GetFullPath(path);parent!=null;parent=Path.GetDirectoryName(parent))if(File.Exists(parent)||Directory.Exists(parent))JsonData.Require((File.GetAttributes(parent)&FileAttributes.ReparsePoint)==0,"native-runtime-link");JsonData.Require(Digest(path)==(string)file.Value,"native-runtime-file-drift");}
   string root=Path.Combine(dataRoot,"native-content",package.BuildId);Directory.CreateDirectory(root);string program=Path.Combine(root,"script.json");var bytes=package.ScriptDefinition;if(File.Exists(program))JsonData.Require(File.ReadAllBytes(program).SequenceEqual(bytes),"native-program-cache-drift");else using(var output=new FileStream(program,FileMode.CreateNew,FileAccess.Write,FileShare.Read)){output.Write(bytes,0,bytes.Length);output.Flush(true);}
   var admitted=NativeScriptDefinition.Admit(bytes);var worker=runtimeManifest["worker_files"] as JObject;JsonData.Require(worker!=null&&worker.Count==3&&worker["ScriptWorker.exe"]!=null,"native-worker-files");var launch=new JObject{{"attempt",Guid.NewGuid().ToString("N")},{"session",config["session"].DeepClone()},{"generation",config["generation"].DeepClone()},{"worker_image",Path.Combine(runtime,"worker")},{"worker_files",worker.DeepClone()},{"attempts",Path.Combine(dataRoot,"native-script-attempts")},{"program",program},{"program_sha256",PackageValidator.Digest(bytes)},{"build",admitted.BuildId}};
   if(admitted.CapabilityTags.Contains("private-storage"))launch["storage"]=new JObject{{"root",Path.Combine(dataRoot,"native-private-storage")},{"installation",Guid.Parse(work).ToString("N")},{"preview",preview}};
   string helper=Path.Combine(runtime,"supervisor","Supervisor.exe");JsonData.Require(files["supervisor/Supervisor.exe"]!=null,"native-helper-files");config["artwork"]=package.SceneId;config["script"]=new JObject{{"node_paths",package.IsExternal?new JArray():manifest["node_paths"].DeepClone()},{"resources",package.IsExternal?new JArray():manifest["resources"].DeepClone()},{"library_digest",package.LibraryDigest},{"source_sha256",package.SceneSourceDigest},{"helper",helper},{"helper_sha256",files["supervisor/Supervisor.exe"].DeepClone()},{"bootstrap_cache",Path.Combine(dataRoot,"native-bootstrap")},{"launch",launch}};if(package.IsExternal)config["external_package"]=new JObject{{"path",package.ArchivePath},{"sha256",package.ArchiveSha256},{"build_id",package.BuildId},{"work_id",package.WorkId},{"revision",package.Revision}};return config;
  }
 }
}
